import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%82%AF%E3%82%A4%E3%83%83%E3%82%AF%E3%82%B9%E3%82%B1%E3%83%83%E3%83%812%E5%91%A8%E7%9B%AE.html","title":"クイックスケッチ2周目","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.46,"words":437},"filePathRelative":"クイックスケッチ2周目.md"}`),a={name:`クイックスケッチ2周目.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="クイックスケッチ2周目" tabindex="-1"><a class="header-anchor" href="#クイックスケッチ2周目"><span>クイックスケッチ2周目</span></a></h1><p><a href="./たてなか流クイックスケッチ.html">たてなか流クイックスケッチ</a>の練習、2周目</p><ul><li><a href="https://sketch.pixiv.net/@karino2" target="_blank" rel="noopener noreferrer">karino2 - pixiv Sketch</a> ここでやってる</li></ul><h2 id="ライブを試みたがいまいち-2026年8月30日" tabindex="-1"><a class="header-anchor" href="#ライブを試みたがいまいち-2026年8月30日"><span>ライブを試みたがいまいち 2026年8月30日</span></a></h2><p>1周目は立体にする、が終わったあたりで挫折してしまった。 とりあえずライブでやっていけば続けられないか？と試してみた。</p><p><a href="./クイックスケッチライブ.html">クイックスケッチライブ</a></p><p>少し試した感じ、いまいち。クイックスケッチでは感覚的なものをいかして全体的な所から捉えていきたいのだが、 喋りながらやると無意識に詳細を描いてしまう、という問題と非常に相性が悪い。</p><p>慣れてくれば出来るのかもしれないが、まずはライブ向きでは無い、という結論になる。</p><h2 id="chapter-3あたりで進まなくなる問題" tabindex="-1"><a class="header-anchor" href="#chapter-3あたりで進まなくなる問題"><span>Chapter 3あたりで進まなくなる問題</span></a></h2><p>なんとなく進めていた所、またChapter 3のあたりで止まる。<a href="./クイックスケッチ1周目.html">クイックスケッチ1周目</a>でも止まったので、ここは挫折ポイントなんじゃないか。</p><p>この本は立体にするあたりから、手本との乖離が大きくなる。</p><p>まぁいいか、とそのまま進めていくと、Cahpter 3の印象を捉える、で、テンプレートを越えて動きの一部をさっと描くためのノウハウを語りだすのだが、 これが高度過ぎて全く出来ない。 これは明らかに難しすぎて今の自分に出来る奴じゃない。</p><p>そもそもテンプレートの所が全然習得出来ている感じじゃないんだよな。 本に描いてあるのを模写するくらいじゃ全然足りないんじゃないか。</p><p>という事で先に進むのではなく、ここまでをもっと練習したい。</p><h2 id="クロッキー的な何か-2026-09-17-木" tabindex="-1"><a class="header-anchor" href="#クロッキー的な何か-2026-09-17-木"><span>クロッキー的な何か 2026-09-17 (木)</span></a></h2><p>Chapter03に進む前に、テンプレートをマスターする必要がある。</p><p>テンプレートは単に言われた通りに曲線にするだけだと、それに立体をつける段になった時に、 いい感じの腕や足の曲線にならない。 一方、たてなか先生のは凄くいい感じになっている。 どうもテンプレートの所の説明に書いてある事以上の何かを意識しながら描いているようだ。 自分もそれをやりたい。</p><p>だが自分の描いたものを、手本と見比べて修正してみたら、どうもいまいち芯を捉えられてないというか、 この本でやりたい事はこれでは無い気がしてくる。</p><p>そこで修正するのでは無く、いまいちだったら描き直す方がいいのでは無いか？と思いつく。 せっかくすぐに描けるスタイルなのだから、いまいちだったらもう一度描き直す方がいいのではないか。 そして何度も描き直していれば、テンプレートレベルがあがっていい感じに描けるようになるんじゃないか？</p><p>という事で同じ絵を何度か気が済むまで描く、を繰り返す事にする。</p><p>書籍やyoutubeの以下のあたりからテンプレートとその立体くらいをひたすら描く、というのをしばらくやってみた。</p><ul><li><a href="https://www.youtube.com/playlist?list=PLKl89tG4IBEvpGLIgVHAhgyhc9win4uAS" target="_blank" rel="noopener noreferrer">たてなか流クイックスケッチ - YouTube</a></li><li><a href="https://www.youtube.com/playlist?list=PLKl89tG4IBEtOAuTURl99gFBO9hpbmmzw" target="_blank" rel="noopener noreferrer">たてなかりゅう「ラクガキ部」 - YouTube</a></li></ul><p>最初はiLMiNAでやってたが、大量に描くと公開するのがかったるい。 そこで最初から公開される所で描きたいと思い、pixiv sketchを使う事にする。</p><p><a href="https://sketch.pixiv.net/@karino2" target="_blank" rel="noopener noreferrer">karino2 - pixiv Sketch</a></p><p>2週間ほどやってみたので、その印象を書いておく。</p><p>このいまいちだったら描き直す、同じ絵を納得行くまで（飽きるまで）何度も描いてみる、というのは、なかなか良い気がしている。 数を描く事でテンプレートに慣れるし、 何度も描き直すと、うまい事感覚を使って全体的な事を意識しながら描ける気がする。 無意識に詳細に行ってしまうのは、気をつけるだけだとなかなか上手く直せないが、 単にそう思ったらもう一回描けばいい。何度か全体を気にしつつ描こうと思いながら描き直していれば、 そのうちいい感じに全体を意識しながら描ける事がある。</p><p>数を描くというのはいい練習方法に思う。</p><p>これは、クロッキーって奴なんじゃないか？という気がしてきている。 ざっと描くのを気が済むまで繰り返す。</p><p>たまになんかを掴めそうな気もしてきているので、しばらく続けていきたい。</p><h2 id="tipsを読み進める-2026-09-25-金" tabindex="-1"><a class="header-anchor" href="#tipsを読み進める-2026-09-25-金"><span>TIPSを読み進める 2026-09-25 (金)</span></a></h2><p>Chapter 3の動画の一部を描くのをそれなりに描いてきた結果、上手くいったり行かなかったりするなぁ、と思っていた。 まぁまぁいい感じと思う所もあるんだが、なんか全然駄目だな、と思う部分もある。 どうも直線的に上手くなっていないので、上達しているのか単なるガチャなのかが良くわからず、 これを続けていけば大丈夫、という確信が持てずにいた。</p><p>そんな折、そういえばChapter 3より先の内容は読んでなかったな、と読み進めていったら、 自分の今の状況に対してのアドバイスのような内容があって、なるほど、こういうものなのか、と自信が持てた。 せっかくなのでTIPSに何が書いてあるのか、何かのヒントがあるかもしれないので読んでいこう、と読んでいた。</p><p>好きなものを深堀りするとかいろいろとやってみようかな、と思う事も書いてあり、今読むのにいいタイミングのようにも思ったので読んでいる。</p>`,33)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};